 const root=new T.Group();scene.add(root);const groups={},covers=[],updates=[],pick=[],c={metal:0x80958b,pale:0xc7d2bc,dark:0x344d44,copper:0xc28b54,oil:0x58b8c7,signal:0xe8ac63,accent:0xc8df75};let current=null,selected=null;
