 for(const x of [-1.7,1.7]){box([.95,.22,1.55],[x,.4,0],'pale',core);for(const z of [-.65,.65])bolt(x,.55,z,core);}
 const primary=group('primary'),secondary=group('secondary');for(const [g,x,color]of [[primary,-1.7,'oil'],[secondary,1.7,'copper']]){for(const y of [1.1,2.85])box([1.04,.12,1.64],[x,y,0],'dark',g);for(let i=0;i<21;i++){const y=1.22+i*.073;wire([[x-.43,y,-.69],[x+.43,y,-.69],[x+.43,y,.69],[x-.43,y,.69],[x-.43,y,-.69]],color,g,.035);}for(const z of [-1.15,1.15]){cyl(.09,.25,[x,.34,z],color,g);wire([[x,.47,z],[x,.8,z],[x+.4,1.22,z>0?.69:-.69]],color,g);}}
 const flux=group('flux'),path=wire([[-1.7,.75,.64],[-1.7,3.22,.64],[1.7,3.22,.64],[1.7,.75,.64],[-1.7,.75,.64]],'accent',flux,.018),dots=particles(path,'accent',flux,26);
 const arrow=new T.ArrowHelper(new T.Vector3(1,0,0),new T.Vector3(0,3.24,.7),.7,c.accent,.2,.12);flux.add(arrow);
