 function startMotion(){if(!motion)motion=requestAnimationFrame(animate);}
 controls.addEventListener('start',()=>{cameraGoal=null;});
 const action=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;section.querySelector('.energy-actions').append(b);return b;};
 const explode=action('Despiece',()=>{goal=goal?0:1;explode.setAttribute('aria-pressed',String(!!goal));explode.textContent=goal?'Ensamblar':'Despiece';startMotion();});explode.dataset.energyExplode='';explode.setAttribute('aria-pressed','false');
 const focus=action('Acercar pieza',()=>{const g=groups[selected];if(!g)return;const bounds=new T.Box3().setFromObject(g),target=bounds.getCenter(new T.Vector3());cameraGoal={target,position:target.clone().add(new T.Vector3(3,2.3,4.5))};startMotion();});focus.dataset.energyFocus='';
 let guided=true;const guidedButton=action('Cámara guiada: sí',()=>{guided=!guided;guidedButton.textContent='Cámara guiada: '+(guided?'sí':'no');guidedButton.setAttribute('aria-pressed',String(guided));});guidedButton.setAttribute('aria-pressed','true');

 function select(name){selected=name;const [title,copy]=info[name]||info.base;section.querySelector('.energy-copy').textContent=title+' — '+copy;section.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.part===name)));for(const [k,g]of Object.entries(groups))g.traverse(o=>{if(o.isMesh&&o.material.emissive)o.material.emissive.setHex(k===name?0x243016:0x000000);});if(guided&&current)focus.click();render();}
